void* allocate_non_paged_pool(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Add space for a header to store the size
    size_t total_size = sizeof(size_t) + size;

    // Check for overflow in the total size calculation
    if (total_size < size) {
        return NULL;
    }

    // Allocate memory with header
    void* pool_block = ExAllocatePoolWithTag(NonPagedPool, total_size, 'POOL');

    if (pool_block == NULL) {
        return NULL;
    }

    // Store the size in the header
    size_t* header = (size_t*)pool_block;
    *header = size;

    // Return pointer to the data portion (after the header)
    return (void*)(header + 1);
}
